<?php require_once '../config/config.php';require_admin();$title='Admin Dashboard';$users=db()->query("SELECT COUNT(*) n FROM users")->fetch()['n'];$recipes=db()->query("SELECT COUNT(*) n FROM recipes")->fetch()['n'];$pending=db()->query("SELECT COUNT(*) n FROM recipes WHERE status='pending'")->fetch()['n'];$messages=db()->query("SELECT COUNT(*) n FROM contact_messages WHERE status='new'")->fetch()['n'];$rs=db()->query("SELECT r.*,CONCAT(u.first_name,' ',u.last_name) author FROM recipes r LEFT JOIN users u ON u.id=r.author_id WHERE r.status='pending' ORDER BY r.created_at DESC")->fetchAll();require '../includes/header.php';?><div class="page-hero"><div class="container"><span class="eyebrow">Administration</span><h1 class="fw-bold">Control room</h1></div></div><section class="section"><div class="container"><div class="row g-3 mb-5"><?php foreach(['Users'=>$users,'Recipes'=>$recipes,'Pending'=>$pending,'Messages'=>$messages] as $k=>$v):?><div class="col-6 col-lg-3"><div class="stat"><?=$k?><h2><?=$v?></h2></div></div><?php endforeach;?></div><h3>Pending community recipes</h3><div class="table-responsive"><table class="table"><tr><th>Recipe</th><th>Author</th><th>Action</th></tr><?php foreach($rs as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['author'])?></td><td><form class="d-inline" method="post" action="review.php"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="status" value="approved"><button class="btn btn-sm btn-success">Approve</button></form> <form class="d-inline" method="post" action="review.php"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="status" value="rejected"><button class="btn btn-sm btn-danger">Reject</button></form></td></tr><?php endforeach;?></table></div></div></section><?php require '../includes/footer.php';?>